use serde::{Deserialize, Serialize};
use serde_with::json::JsonString;
use serde_with::serde_as;

#[serde_as]
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type",rename_all="kebab-case")]
pub enum Message {
    Notification{#[serde_as(as = "JsonString")] content: vrchatapi::models::notification::Notification},
    ResponseNotification{#[serde_as(as = "JsonString")] content: response_notification::ResponseNotification},
    SeeNotification{#[serde(rename = "content")] notification_id: String},
    HideNotification{#[serde(rename = "content")] notification_id: String},
    ClearNotification, //no content to parse
    NotificationV2{#[serde_as(as = "JsonString")] content: notification_v2::NotificationV2},
    NotificationV2Update{#[serde_as(as = "JsonString")] content: notification_v2::update::NotificationV2Update},
    NotificationV2Delete{#[serde_as(as = "JsonString")] content: notification_v2::delete::NotificationV2Delete},
    FriendAdd{#[serde_as(as = "JsonString")] content: friend::add::FriendAdd},
    FriendDelete{#[serde_as(as = "JsonString")] content: friend::delete::FriendDelete},
    FriendOnline{#[serde_as(as = "JsonString")] content: friend::online::FriendOnline},
    FriendActive{#[serde_as(as = "JsonString")] content: friend::active::FriendActive},
    FriendOffline{#[serde_as(as = "JsonString")] content: friend::offline::FriendOffline},
    FriendUpdate{#[serde_as(as = "JsonString")] content: friend::update::FriendUpdate},
    FriendLocation{#[serde_as(as = "JsonString")] content: friend::location::FriendLocation},
    UserUpdate{#[serde_as(as = "JsonString")] content: user::update::UserUpdate},
    UserLocation{#[serde_as(as = "JsonString")] content: user::location::UserLocation},
    UserBadgeAssigned{#[serde_as(as = "JsonString")] content: user::badge::UserBadgeAssigned},
    UserBadgeUnassigned{#[serde_as(as = "JsonString")] content: user::badge::UserBadgeUnassigned},
    ContentRefresh{#[serde_as(as = "JsonString")] content: content_refresh::ContentRefresh},
    InstanceQueueJoined{#[serde_as(as = "JsonString")] content: instance_queue::InstanceQueueJoined},
    InstanceQueueReady{#[serde_as(as = "JsonString")] content: instance_queue::InstanceQueueReady},
    GroupJoined{#[serde_as(as = "JsonString")] content: group::GroupJoined},
    GroupLeft{#[serde_as(as = "JsonString")] content: group::GroupLeft },
    GroupMemberUpdated{#[serde_as(as = "JsonString")] content: group::GroupMemberUpdated },
    GroupRoleUpdated{#[serde_as(as = "JsonString")] content: group::GroupRoleUpdated},
}

